-- Initialize P6 and P9 aisle definitions. The line_info primary key is generated by AUTO_INCREMENT.
-- Each insert is idempotent so deployment scripts can be run repeatedly.

INSERT INTO line_info (
    code, name, type, ware_code, ware_name, area_code, area_name,
    inven_state, task_state, disable_state, is_delete, version,
    create_time, create_user_id, create_user_name,
    update_time, update_user_id, update_user_name,
    max_y, min_y, max_z, model_data, start_direction
)
SELECT
    'P6-1', 'P6-1', 'line', 'P6', 'P6', 'P6', 'P6',
    0, 0, 0, 0, '1',
    '2026-10-23 08:49:56', 1, 'admin',
    '2026-10-23 08:52:28', 1, 'admin',
    31, 1, 8, NULL, ''
WHERE NOT EXISTS (
    SELECT 1 FROM line_info WHERE code = 'P6-1' AND ware_code = 'P6'
);

